    public string UserSessionId
    {
        get
        {
            //Session ID= -1 >>> API
            if (System.Web.HttpContext.Current == null) //&& System.Web.HttpContext.Current.Session["uid"] == null)
            {
                return "-1";
            }

            if (System.Web.HttpContext.Current.Session["uid"] == null) return "";
            return System.Web.HttpContext.Current.Session["uid"].ToString();
        }
    }
