    public enum TraceLogOperationType
    {
        None = 0,
        Insert = 1,
        Update = 2,
        Delete = 3
    }


    public void CreateAudit(SqlCommand cmd, TraceLogOperationType oType, string pKey, string commandMethod)
    {
        try
        {
            string commandText = "";
            string userId = UserSessionId;

            if (cmd == null) return;

            commandText = cmd.CommandText;

            Dictionary<string, string> parameters = CreateParameterCollection(cmd.Parameters);
            string resultXml = ToXml(parameters, "AuditLogs", "log");

            InsertAuditLog(pKey, oType.ToString(), userId, resultXml, commandMethod, commandText);

        }
        catch (Exception ex)
        {
            // no throw

        }


    }

    private Dictionary<string, string> CreateParameterCollection(SqlParameterCollection paramCol)
    {
        if (paramCol == null || paramCol.Count == 0) return new Dictionary<string, string>(); ;

        Dictionary<string, string> result = new Dictionary<string, string>();

        foreach (SqlParameter param in paramCol)
        {
            result.Add(param.ParameterName.Substring(1, param.ParameterName.Length - 1), param.Value.ToString());
        }

        return result;
    }
    public string ToXml(Dictionary<string, string> input, string root, string element)
    {
        if (input == null) return "";
        XElement xmlDoc = new XElement(root,
                      (from dRow in input.AsEnumerable()
                       select new XElement(element,
                           new XElement("ColumnName", dRow.Key),
                           new XElement("ColumnValue", dRow.Value))


          ).Distinct());

        return (xmlDoc.ToString());

    }



