    internal void UpdateCashPlusActivitiesLIPW(string intWorkActivityId, string intBenId, string attendanceDate, bool FLI, bool ECD, bool WASH)
    {
        try
        {
            con.OpenConnection();// dbu.openCon();
            SqlCommand cmd = new SqlCommand("UpdateCashPlusActivitiesLIPW", con.GetConnection);
            cmd.CommandType = CommandType.StoredProcedure;

            cmd.Parameters.Add("@intWorkActivityId", SqlDbType.VarChar).Value = intWorkActivityId;
            cmd.Parameters.Add("@intBenId", SqlDbType.VarChar).Value = intBenId;
            cmd.Parameters.Add("@AttendanceDate", SqlDbType.DateTime).Value = cmf.convertDateIndia(attendanceDate.Trim());
            cmd.Parameters.Add("@FLI", SqlDbType.VarChar).Value = (FLI ? "1" : "0");
            cmd.Parameters.Add("@ECD", SqlDbType.VarChar).Value = (ECD ? "1" : "0");
            cmd.Parameters.Add("@WASh", SqlDbType.VarChar).Value = (WASH ? "1" : "0");

            cmd.ExecuteNonQuery();

            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];
                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(cmd, TraceLogOperationType.Insert, intWorkActivityId, "UpdateCashPlusActivitiesLIPW");
                }
            }
            catch (Exception) { }
            #endregion

            con.CloseConnection();
        }
        catch (Exception ex)
        {
            con.CloseConnection();
            throw ex;
        }
    }


