    internal int getWageAttachmentStoredCount(string reqNo)
    {
        con.OpenConnection();
        SqlDataAdapter da;
        DataSet ds = new DataSet();
        int iAttachcount = 0;

        try
        {
            da = new SqlDataAdapter("getWageAttachmentStoredCount", con.GetConnection);
            da.SelectCommand.CommandType = CommandType.StoredProcedure;

            da.SelectCommand.Parameters.Add("@reqNo", SqlDbType.VarChar).Value = reqNo;

            da.Fill(ds);
            con.CloseConnection();

            if (ds.Tables.Count > 0 && ds.Tables[0].Rows.Count > 0 && ds.Tables[0].Rows[0]["AttachCount"] != null)
            {
                string strAttachCount = ds.Tables[0].Rows[0][0].ToString();
                iAttachcount = Convert.ToInt32(strAttachCount);
            }
            else
            {
                iAttachcount = 0;
            }

            return iAttachcount;
        }
        catch (Exception ex)
        {
            throw ex;
        }
        finally
        {
            con.CloseConnection();
        }
    }




