    internal void DeleteWageRequestAttachment(int ImageId)
    {
        SqlCommand cmd = new SqlCommand();
        cmd.CommandType = CommandType.StoredProcedure;
        cmd.CommandText = "DeleteWageRequestAttachment";

        cmd.Parameters.Add("@intImageId", SqlDbType.VarChar).Value = ImageId;

        con.OpenConnection();
        cmd.Connection = con.GetConnection;

        try
        {
            cmd.ExecuteNonQuery();

            #region TraceLog Implementation
            string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

            if (appSettingValue != null && appSettingValue.ToLower() == "true")
            {
                CreateAudit(cmd, TraceLogOperationType.Delete, ImageId.ToString(), "DeleteWageRequestAttachment");
            }

            #endregion
        }
        catch (Exception ex)
        {
            throw ex;
        }
        finally
        {
            cmd.Dispose();
            con.CloseConnection();
        }
    }

