    // To Delete Beneficiary
    public int DeleteBenficiary(string intBenid, string DeletedBy)
    {
        int value = 0;

        try
        {
            con.OpenConnection();// dbu.openCon();
            SqlCommand cmd = new SqlCommand("DeleteBenficiarynew", con.GetConnection);
            cmd.CommandType = CommandType.StoredProcedure;



            cmd.Parameters.Add("@intBenid", SqlDbType.VarChar).Value = intBenid.Trim();
            cmd.Parameters.Add("@DeletedBy", SqlDbType.VarChar).Value = DeletedBy.Trim();

            string val = cmd.ExecuteScalar().ToString();
            if (val != string.Empty)
                value = Int32.Parse(val);


            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(cmd, TraceLogOperationType.Delete, intBenid.ToString(), "DeleteBenficiary");
                }

            }
            catch (Exception) { }
            #endregion

            con.CloseConnection();
        }
        catch (Exception ex)
        {
            con.CloseConnection();
            throw ex;
        }

        return value;
    }
