    /// <summary>
    /// If beneficiaries with an existing Wage Request for set "year-month-paymentCycle" exist it returns "true", if not "false"
    /// </summary>
    /// <param name="year">WR year</param>
    /// <param name="month">WR month</param>
    /// <param name="paymentCycle">Payemnt Cycle</param>
    /// <param name="boma">Boma ID</param>
    /// <param name="selectedBeneficiariesList">List (comma separated) of beneficiaries to check</param>
    /// <returns>
    /// true/false if beneficairies associated to WR with set parameters exist/not exist
    /// </returns>
    internal bool CheckWageRequestDuplicate(string year, string month, string paymentCycle, string boma, string selectedBeneficiariesList)
    {
        try
        {
            con.OpenConnection();// dbu.openCon();
            SqlCommand cmd = new SqlCommand("CheckWageRequestDuplicate", con.GetConnection);
            cmd.CommandType = CommandType.StoredProcedure;
            cmd.Parameters.Add("@year", SqlDbType.VarChar).Value = year;
            cmd.Parameters.Add("@month", SqlDbType.VarChar).Value = month;
            cmd.Parameters.Add("@paymentCycle", SqlDbType.VarChar).Value = paymentCycle;
            cmd.Parameters.Add("@bomaID", SqlDbType.VarChar).Value = boma;
            cmd.Parameters.Add("@Benids", SqlDbType.VarChar).Value = selectedBeneficiariesList;

            int result = Convert.ToInt32(cmd.ExecuteScalar());
            con.CloseConnection();

            if (result > 0)
            {
                return true;
            }
            else
            {
                return false;
            }
        }
        catch (Exception ex)
        {
            con.CloseConnection();
            throw ex;
        }
    }


