            SqlBulkCopyColumnMapping mapping1 = new SqlBulkCopyColumnMapping("intWagePaymentReqid", "intWagePaymentReqid");
            SqlBulkCopyColumnMapping mapping2 = new SqlBulkCopyColumnMapping("Description", "Description");
            SqlBulkCopyColumnMapping mapping3 = new SqlBulkCopyColumnMapping("PhotoFileName", "PhotoFileName");
            SqlBulkCopyColumnMapping mapping4 = new SqlBulkCopyColumnMapping("PhotoFilePath", "PhotoFilePath");
            SqlBulkCopyColumnMapping mapping11 = new SqlBulkCopyColumnMapping("Created_by", "Created_by");


            bulkCopy.ColumnMappings.Add(mapping1);
            bulkCopy.ColumnMappings.Add(mapping2);
            bulkCopy.ColumnMappings.Add(mapping3);
            bulkCopy.ColumnMappings.Add(mapping4);
            bulkCopy.ColumnMappings.Add(mapping11);



            bulkCopy.DestinationTableName = ("tbl_WageAttachements");
            bulkCopy.WriteToServer(dt);
            i = 1;

        }
        catch (Exception ex)
        {
            i = 0;
        }
        finally
        {
            con.CloseConnection();
        }

        return i;


    }

