                cmd.Parameters.Add("@EnvironmentSocialImpact", SqlDbType.VarChar).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@EnvironmentSocialImpact", SqlDbType.VarChar).Value = EnvironmentImpact.Trim();

            if (ProposedMitigationMeasure.Trim() == "" || ProposedMitigationMeasure.Trim() == null)
                cmd.Parameters.Add("@ProposedMitigationMeasure", SqlDbType.VarChar).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@ProposedMitigationMeasure", SqlDbType.VarChar).Value = ProposedMitigationMeasure.Trim();

            if (MitigationMeasure == "" || MitigationMeasure == null)
                cmd.Parameters.Add("@MitigationMeasureImplemented", SqlDbType.VarChar).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@MitigationMeasureImplemented", SqlDbType.VarChar).Value = MitigationMeasure.Trim();

            if (PerformanceIndicator.Trim() == "" || PerformanceIndicator.Trim() == null)
                cmd.Parameters.Add("@PerformanceIndicators", SqlDbType.VarChar).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@PerformanceIndicators", SqlDbType.VarChar).Value = PerformanceIndicator.Trim();



            if (filePath.Trim() == "" || filePath.Trim() == null)
                cmd.Parameters.Add("@FilePath", SqlDbType.VarChar).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@FilePath", SqlDbType.VarChar).Value = filePath.Trim();

            if (fileName.Trim() == "" || fileName.Trim() == null)
                cmd.Parameters.Add("@FileName", SqlDbType.VarChar).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@FileName", SqlDbType.VarChar).Value = fileName.Trim();


            string val = cmd.ExecuteScalar().ToString();
            if (val != string.Empty)
                value = Int32.Parse(val);


            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(cmd, TraceLogOperationType.Insert, value.ToString(), "InsertEnviMan");
                }

            }
            catch (Exception) { }
            #endregion

            con.CloseConnection();
        }
        catch (Exception ex)
        {
            con.CloseConnection();
            throw ex;
        }

        return value;
    }

