    //Created by siva as on 7-1-2016 :: Funds Allocation
    public int UpdFundRaising(string intWorklId, string FundRaiseDate, string FundRaiseAmount, string Remarks, string Created_by, string CoOrdinator_Id, string Specialist_Id, string Manager_Id)
    {
        SqlCommand com = new SqlCommand();
        com.CommandType = CommandType.StoredProcedure;
        com.CommandText = "UpdFundRaising";



        if (intWorklId == "" || intWorklId == null)
            com.Parameters.Add("@intWorklId", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intWorklId", SqlDbType.VarChar).Value = intWorklId.Trim();


        if (FundRaiseDate == "" || FundRaiseDate == null)
            com.Parameters.Add("@FundRaiseDate", SqlDbType.DateTime).Value = DBNull.Value;
        else
            com.Parameters.Add("@FundRaiseDate", SqlDbType.DateTime).Value = cmf.convertDateIndia(FundRaiseDate.Trim());


        if (FundRaiseAmount == "" || FundRaiseAmount == null)
            com.Parameters.Add("@FundRaiseAmount", SqlDbType.Decimal).Value = DBNull.Value;
        else
            com.Parameters.Add("@FundRaiseAmount", SqlDbType.Decimal).Value = FundRaiseAmount.Trim();

        if (Remarks == "" || Remarks == null)
            com.Parameters.Add("@Remarks", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Remarks", SqlDbType.VarChar).Value = Remarks.Trim();



        if (Created_by == "" || Created_by == null)
            com.Parameters.Add("@Created_by", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Created_by", SqlDbType.VarChar).Value = Created_by.Trim();

        if (CoOrdinator_Id == "" || CoOrdinator_Id == null)
            com.Parameters.Add("@CoOrdinator_Id", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@CoOrdinator_Id", SqlDbType.VarChar).Value = CoOrdinator_Id.Trim();

        if (Specialist_Id == "" || Specialist_Id == null)
            com.Parameters.Add("@Specialist_Id", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Specialist_Id", SqlDbType.VarChar).Value = Specialist_Id.Trim();

        if (Manager_Id == "" || Manager_Id == null)
            com.Parameters.Add("@Manager_Id", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Manager_Id", SqlDbType.VarChar).Value = Manager_Id.Trim();

        con.OpenConnection();
        com.Connection = con.GetConnection;

        try
        {
            //return com.ExecuteNonQuery();
            int result = Convert.ToInt32(com.ExecuteScalar());


            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(com, TraceLogOperationType.Update, intWorklId.ToString(), "UpdFundRaising");
                }

            }
            catch (Exception) { }
            #endregion

            return result;

        }
        catch (Exception ex)
        {

            throw ex;
            return 0;
        }
        finally
        {
            com.Dispose();
            con.CloseConnection();
        }
    }




