    public int UpdFundApproved(string intWorklId, string ApprovedDate, string PaymentMode, string TransactionNo, string PaymentDate, string PaidAmt, string Created_by, string invoiceid, string InvoiceStatus, string intFromid, string intToid, string InvoiceRemarks)
    {
        SqlCommand com = new SqlCommand();
        com.CommandType = CommandType.StoredProcedure;
        com.CommandText = "UpdFundApproved";



        if (intWorklId == "" || intWorklId == null)
            com.Parameters.Add("@intWorklId", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intWorklId", SqlDbType.VarChar).Value = intWorklId.Trim();


        if (TransactionNo == "" || TransactionNo == null)
            com.Parameters.Add("@TransactionNo", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@TransactionNo", SqlDbType.VarChar).Value = TransactionNo.Trim();


        if (ApprovedDate == "" || ApprovedDate == null)
            com.Parameters.Add("@ApprovedDate", SqlDbType.DateTime).Value = DBNull.Value;
        else
            com.Parameters.Add("@ApprovedDate", SqlDbType.DateTime).Value = cmf.convertDateIndia(ApprovedDate.Trim());


        if (PaymentDate == "" || PaymentDate == null)
            com.Parameters.Add("@PaymentDate", SqlDbType.DateTime).Value = DBNull.Value;
        else
            com.Parameters.Add("@PaymentDate", SqlDbType.DateTime).Value = cmf.convertDateIndia(PaymentDate.Trim());


        if (PaidAmt == "" || PaidAmt == null)
            com.Parameters.Add("@PaidAmt", SqlDbType.Decimal).Value = DBNull.Value;
        else
            com.Parameters.Add("@PaidAmt", SqlDbType.Decimal).Value = PaidAmt.Trim();

        if (PaymentMode == "" || PaymentMode == null)
            com.Parameters.Add("@PaymentMode", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@PaymentMode", SqlDbType.VarChar).Value = PaymentMode.Trim();



        if (Created_by == "" || Created_by == null)
            com.Parameters.Add("@Created_by", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Created_by", SqlDbType.VarChar).Value = Created_by.Trim();


        if (invoiceid == "" || invoiceid == null)
            com.Parameters.Add("@invoiceid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@invoiceid", SqlDbType.VarChar).Value = invoiceid.Trim();


        if (InvoiceStatus == "" || InvoiceStatus == null)
            com.Parameters.Add("@InvoiceStatus", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@InvoiceStatus", SqlDbType.VarChar).Value = InvoiceStatus.Trim();

        if (intFromid == "" || intFromid == null)
            com.Parameters.Add("@intFromid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intFromid", SqlDbType.VarChar).Value = intFromid.Trim();


        if (intToid == "" || intToid == null)
            com.Parameters.Add("@intToid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intToid", SqlDbType.VarChar).Value = intToid.Trim();

        if (InvoiceRemarks == "" || InvoiceRemarks == null)
            com.Parameters.Add("@InvoiceRemarks", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@InvoiceRemarks", SqlDbType.VarChar).Value = InvoiceRemarks.Trim();

        con.OpenConnection();
        com.Connection = con.GetConnection;

        try
        {
            //return com.ExecuteNonQuery();
            int result = Convert.ToInt32(com.ExecuteScalar());


            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(com, TraceLogOperationType.Update, intWorklId.ToString(), "UpdFundApproved");
                }

            }
            catch (Exception) { }
            #endregion


            return result;

        }
        catch (Exception ex)
        {

            throw ex;
            return 0;
        }
        finally
        {
            com.Dispose();
            con.CloseConnection();
        }
    }

