    public int UpdWorkCode(string intWorkid, string WorkCode)
    {
        SqlCommand com = new SqlCommand();
        com.CommandType = CommandType.StoredProcedure;
        com.CommandText = "UpdWorkCode";




        if (intWorkid == "" || intWorkid == null)
            com.Parameters.Add("@intWorkid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intWorkid", SqlDbType.VarChar).Value = intWorkid.Trim();

        if (WorkCode == "" || WorkCode == null)
            com.Parameters.Add("@WorkCode", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@WorkCode", SqlDbType.VarChar).Value = WorkCode.Trim();

        con.OpenConnection();
        com.Connection = con.GetConnection;

        try
        {
            int result = com.ExecuteNonQuery();

            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(com, TraceLogOperationType.Update, intWorkid.ToString(), "UpdWorkCode");
                }

            }
            catch (Exception) { }
            #endregion

            return result;

        }
        catch (Exception ex)
        {

            throw ex;
            return 0;
        }
        finally
        {
            com.Dispose();
            con.CloseConnection();
        }

    }

