    //siva as on 19-01-2016 for for Get beneficiary Wages Payment
    public int InsUpdBeneficiaryWagesFromToDate(string intBenid, string FromDate, string ToDate, string PaidDate, string PaidAmount, string Created_by, string Wagerate)
    {
        int value = 0;

        try
        {
            con.OpenConnection();// dbu.openCon();
            SqlCommand cmd = new SqlCommand("InsUpdBeneficiaryWagesFromToDate", con.GetConnection);
            cmd.CommandType = CommandType.StoredProcedure;

            if (PaidAmount == "" || PaidAmount == null)
                cmd.Parameters.Add("@PaidAmount", SqlDbType.Decimal).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@PaidAmount", SqlDbType.Decimal).Value = PaidAmount.Trim();

            if (Wagerate == "" || Wagerate == null || Wagerate == "--Select--")
                cmd.Parameters.Add("@Wagerate", SqlDbType.VarChar).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@Wagerate", SqlDbType.VarChar).Value = Wagerate.Trim();



            if (FromDate == "" || FromDate == null)
                cmd.Parameters.Add("@FromDate", SqlDbType.VarChar).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@FromDate", SqlDbType.DateTime).Value = cmf.convertDateIndia(FromDate.Trim());


            if (ToDate == "" || ToDate == null)
                cmd.Parameters.Add("@ToDate", SqlDbType.VarChar).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@ToDate", SqlDbType.DateTime).Value = cmf.convertDateIndia(ToDate.Trim());

            cmd.Parameters.Add("@intBenid", SqlDbType.VarChar).Value = intBenid.Trim();


            if (PaidDate == "" || PaidDate == null)
                cmd.Parameters.Add("@PaidDate", SqlDbType.DateTime).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@PaidDate", SqlDbType.DateTime).Value = cmf.convertDateIndia(PaidDate.Trim());

            if (Created_by.Trim() == "" || Created_by.Trim() == null)
                cmd.Parameters.Add("@Created_by", SqlDbType.VarChar).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@Created_by", SqlDbType.VarChar).Value = Created_by.Trim();


            string val = cmd.ExecuteScalar().ToString();
            if (val != string.Empty)
                value = Int32.Parse(val);



            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(cmd, TraceLogOperationType.Insert, intBenid.ToString(), "InsUpdBeneficiaryWagesFromToDate");
                }

            }
            catch (Exception) { }
            #endregion

            con.CloseConnection();
        }
        catch (Exception ex)
        {
            con.CloseConnection();
            throw ex;
        }

        return value;
    }
