    //Added by Rushi
    private void BinaryToImage(string b, string EnrollmentNo)
    {

        using (MemoryStream ms = new MemoryStream(Convert.FromBase64String(b)))
        {

            using (System.Drawing.Bitmap image = new System.Drawing.Bitmap(ms))
            {
                string targetPath = HttpContext.Current.Server.MapPath("~/BenImages/");
                bool isExists = System.IO.Directory.Exists(@targetPath);
                if (!isExists)
                {
                    System.IO.Directory.CreateDirectory(@targetPath);
                }
                string fileName = EnrollmentNo + ".jpg";
                string filePath1 = HttpContext.Current.Server.MapPath("~/BenImages/") + fileName;
                image.Save(@filePath1);

            }
        }
    }
    public string ImageToBase64(string Path)
    {
        using (System.Drawing.Image image = System.Drawing.Image.FromFile(Path))
        {
            using (MemoryStream m = new MemoryStream())
            {
                image.Save(m, image.RawFormat);
                byte[] imageBytes = m.ToArray();

                // Convert byte[] to Base64 String
                string base64String = Convert.ToBase64String(imageBytes);
                return base64String;
            }
        }
    }
