    public int bulkInsertdrWorkProgressPhto(DataTable dt, int IntWorkDetailsTypeId)
    {
        con.OpenConnection();
        foreach (DataRow dr in dt.Rows)
        { dr["IntWorkDetailsTypeId"] = IntWorkDetailsTypeId; }
        int i = 0;

        try
        {
            SqlBulkCopy bulkCopy = new SqlBulkCopy(con.GetConnection);

            SqlBulkCopyColumnMapping mapping1 = new SqlBulkCopyColumnMapping("intWorkid", "intTypeId");
            SqlBulkCopyColumnMapping mapping2 = new SqlBulkCopyColumnMapping("DocumentName", "PhotoFileName");
            SqlBulkCopyColumnMapping mapping3 = new SqlBulkCopyColumnMapping("WorkPhoto", "File_Path");
            SqlBulkCopyColumnMapping mapping4 = new SqlBulkCopyColumnMapping("Status", "Type");

            SqlBulkCopyColumnMapping mapping5 = new SqlBulkCopyColumnMapping("Created_by", "Created_by");
            SqlBulkCopyColumnMapping mapping6 = new SqlBulkCopyColumnMapping("Created_dt", "Created_dt");
            SqlBulkCopyColumnMapping mapping7 = new SqlBulkCopyColumnMapping("IntWorkDetailsTypeId", "IntWorkDetailsTypeId");


            bulkCopy.ColumnMappings.Add(mapping1);
            bulkCopy.ColumnMappings.Add(mapping2);
            bulkCopy.ColumnMappings.Add(mapping3);
            bulkCopy.ColumnMappings.Add(mapping4);
            bulkCopy.ColumnMappings.Add(mapping5);
            bulkCopy.ColumnMappings.Add(mapping6);
            bulkCopy.ColumnMappings.Add(mapping7);
            bulkCopy.DestinationTableName = ("tbl_Attachements");
            bulkCopy.WriteToServer(dt);
            i = 1;

        }
        catch (Exception ex)
        {
            i = 0;
        }
        finally
        {
            con.CloseConnection();
        }

        return i;


    }



