    public string UpdateFinancialStatus(string invoiceid, string InvoiceStatus, string InvoiceRemarks, string ApprovedDate, string Modified_by, string intFromid, string intToid)
    {
        int value = 0;

        try
        {
            con.OpenConnection();// dbu.openCon();
            SqlCommand cmd = new SqlCommand("UpdateFinancialStatus", con.GetConnection);
            cmd.CommandType = CommandType.StoredProcedure;

            try
            {
                cmd.Parameters.Add("@invoiceid", SqlDbType.Int).Value = Convert.ToInt32(invoiceid);
            }
            catch
            {
                return "Please Select Corrent InvoiceId";
            }

            if (InvoiceStatus == "" || InvoiceStatus == null || InvoiceStatus == "--Select--")
            {
                return "Please Select Status";
            }
            else
            {
                try
                {
                    cmd.Parameters.Add("@InvoiceStatus", SqlDbType.VarChar).Value = InvoiceStatus.Trim();
                }
                catch
                {
                    return "Please Select Status";
                }
            }

            //if (InvoiceRemarks == "" || InvoiceRemarks == null || InvoiceRemarks == "--Select--")
            //{
            //    return "Please Enter Remarks";
            //}
            //else
            //{
            //    try
            //    {
            cmd.Parameters.Add("@InvoiceRemarks", SqlDbType.VarChar).Value = InvoiceRemarks.Trim();
            //    }
            //    catch
            //    {
            //        return "Please Enter Remarks";
            //    }
            //}


            try
            {
                cmd.Parameters.Add("@ApprovedDate", SqlDbType.DateTime).Value = cmf.convertDateIndia(ApprovedDate.Trim());
            }
            catch
            {
                return "Please Enter Correct Date";
            }
            try
            {
                cmd.Parameters.Add("@Modified_by", SqlDbType.Int).Value = Convert.ToInt32(Modified_by);
            }
            catch
            {
                return "Please Select Corrent Modified User";
            }
            try
            {
                cmd.Parameters.Add("@intFromid", SqlDbType.Int).Value = Convert.ToInt32(intFromid);
            }
            catch
            {
                return "Please Select  FromUser";
            }
            try
            {
                cmd.Parameters.Add("@intToid", SqlDbType.Int).Value = Convert.ToInt32(intToid);
            }
            catch
            {
                return "Please Select  ToUser";
            }




            int val = cmd.ExecuteNonQuery();
            con.CloseConnection();
            if (val == 0)
            { return "Error"; }
            else { return "Success"; }


        }
        catch (Exception ex)
        {
            con.CloseConnection();
            throw ex;
        }

        return "";
    }

    public int DeleteBenefeciaryAttendance(string WorkCode, string AttendanceDate, string groupType)
    {
        int value = 0;

        try
        {
            con.OpenConnection();// dbu.openCon();
            SqlCommand cmd = new SqlCommand("DeleteBenefeciaryAttendance", con.GetConnection);
            cmd.CommandType = CommandType.StoredProcedure;




            if (WorkCode == "" || WorkCode == null)
                cmd.Parameters.Add("@WorkCode", SqlDbType.VarChar).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@WorkCode", SqlDbType.VarChar).Value = WorkCode.Trim();




            if (AttendanceDate == "" || AttendanceDate == null)
                cmd.Parameters.Add("@AttendanceDate", SqlDbType.DateTime).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@AttendanceDate", SqlDbType.DateTime).Value = cmf.convertDateIndia(AttendanceDate.Trim());

            if (groupType == "" || groupType == null)
                cmd.Parameters.Add("@groupType", SqlDbType.VarChar).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@groupType", SqlDbType.VarChar).Value = groupType.Trim();



            string val = cmd.ExecuteScalar().ToString();
            if (val != string.Empty)
                value = Int32.Parse(val);



            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(cmd, TraceLogOperationType.Delete, WorkCode.ToString(), "DeleteBenefeciaryAttendance");
                }

            }
            catch (Exception) { }
            #endregion


            con.CloseConnection();
        }
        catch (Exception ex)
        {
            con.CloseConnection();
            throw ex;
        }

        return value;
    }


    public int InsertUpdateAttachements_Sp(string status, string type_id, string photo_file_name, string created_by, string File_Name)
    {
        SqlCommand com = new SqlCommand();
        com.CommandType = CommandType.StoredProcedure;
        com.CommandText = "InsertUpdateAttachements_Sp";


        //,string ,string ,



        com.Parameters.Add("@Type", SqlDbType.VarChar).Value = status;
        com.Parameters.Add("@intTypeId", SqlDbType.Int).Value = type_id;
        com.Parameters.Add("@PhotoFileName", SqlDbType.VarChar).Value = photo_file_name;
        com.Parameters.Add("@Created_by", SqlDbType.Int).Value = created_by;
        com.Parameters.Add("@FileName", SqlDbType.VarChar).Value = File_Name;


        con.OpenConnection();
        com.Connection = con.GetConnection;

        try
        {
            com.ExecuteNonQuery();


            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(com, TraceLogOperationType.Insert, type_id.ToString(), "InsertUpdateAttachements_Sp");
                }

            }
            catch (Exception) { }
            #endregion
            return 1;
        }
        catch (Exception ex)
        {

            throw ex;
            return 0;
        }
        finally
        {
            com.Dispose();
            con.CloseConnection();
        }
    }


