    //Grievence Reg
    public string InsUpdGrievance_Registration(string Grievance_RegistrationNo, string intStateid, string intCountieid, string intPayamid, string intBomasid, string Complainant_Name, string Complainant_EnrolmentNo, string TypeOfComplaints, string DetailsComplainsReported, string ComplaintRegisteredDate, string Accused_Name, string Accused_EnrolmentNo, string Accused_Complaints_Specification, string Accused_ComplainsReferred, string Created_by)
    {
        SqlCommand com = new SqlCommand();
        com.CommandType = CommandType.StoredProcedure;
        com.CommandText = "InsUpdGrievance";





        com.Parameters.Add("@Grievance_RegistrationNo", SqlDbType.VarChar).Value = Grievance_RegistrationNo.Trim();
        if (intStateid == "" || intStateid == null)
            com.Parameters.Add("@intStateid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intStateid", SqlDbType.VarChar).Value = intStateid.Trim();

        if (intCountieid == "" || intCountieid == null)
            com.Parameters.Add("@intCountieid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intCountieid", SqlDbType.VarChar).Value = intCountieid.Trim();

        if (intPayamid == "" || intPayamid == null)
            com.Parameters.Add("@intPayamid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intPayamid", SqlDbType.VarChar).Value = intPayamid.Trim();

        if (intBomasid == "" || intBomasid == null)
            com.Parameters.Add("@intBomasid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intBomasid", SqlDbType.VarChar).Value = intBomasid.Trim();




        if (Complainant_Name == "" || Complainant_Name == null)
            com.Parameters.Add("@Complainant_Name", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Complainant_Name", SqlDbType.VarChar).Value = Complainant_Name.Trim();


        if (Complainant_EnrolmentNo == "" || Complainant_EnrolmentNo == null)
            com.Parameters.Add("@Complainant_EnrolmentNo", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Complainant_EnrolmentNo", SqlDbType.VarChar).Value = Complainant_EnrolmentNo.Trim();

        if (TypeOfComplaints == "" || TypeOfComplaints == null)
            com.Parameters.Add("@TypeOfComplaints", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@TypeOfComplaints", SqlDbType.VarChar).Value = TypeOfComplaints.Trim();
        if (DetailsComplainsReported == "" || DetailsComplainsReported == null)
            com.Parameters.Add("@DetailsComplainsReported", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@DetailsComplainsReported", SqlDbType.VarChar).Value = DetailsComplainsReported.Trim();

        if (ComplaintRegisteredDate == "" || ComplaintRegisteredDate == null)
            com.Parameters.Add("@ComplaintRegisteredDate", SqlDbType.DateTime).Value = DBNull.Value;
        else
            com.Parameters.Add("@ComplaintRegisteredDate", SqlDbType.DateTime).Value = cmf.convertDateIndia(ComplaintRegisteredDate.Trim());

        if (Accused_Name == "" || Accused_Name == null)
            com.Parameters.Add("@Accused_Name", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Accused_Name", SqlDbType.VarChar).Value = Accused_Name.Trim();
        if (Accused_EnrolmentNo == "" || Accused_EnrolmentNo == null)
            com.Parameters.Add("@Accused_EnrolmentNo", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Accused_EnrolmentNo", SqlDbType.VarChar).Value = Accused_EnrolmentNo.Trim();

        if (Accused_Complaints_Specification == "" || Accused_Complaints_Specification == null)
            com.Parameters.Add("@Accused_Complaints_Specification", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Accused_Complaints_Specification", SqlDbType.VarChar).Value = Accused_Complaints_Specification.Trim();


        if (Accused_ComplainsReferred == "" || Accused_ComplainsReferred == null)
            com.Parameters.Add("@Accused_ComplainsReferred", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Accused_ComplainsReferred", SqlDbType.VarChar).Value = Accused_ComplainsReferred.Trim();

        if (Created_by == "" || Created_by == null)
            com.Parameters.Add("@Created_by", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Created_by", SqlDbType.VarChar).Value = Created_by.Trim();


        com.Parameters.Add("@Grievance_RegistrationNoOut", SqlDbType.NVarChar, 500);
        com.Parameters["@Grievance_RegistrationNoOut"].Direction = ParameterDirection.Output;

        con.OpenConnection();
        com.Connection = con.GetConnection;

        try
        {
            com.ExecuteNonQuery().ToString();
            string i = com.Parameters["@Grievance_RegistrationNoOut"].Value.ToString();
            return i;
            // return Convert.ToInt32(com.ExecuteScalar());
        }
        catch (Exception ex)
        {

            throw ex;
            //  return 0;
        }
        finally
        {
            com.Dispose();
            con.CloseConnection();
        }
    }

