    #region API Integration

    public int InsertDataUsingAPI(string intIP, string household_number, string BeneficiaryType,
                                            string GroupId, string supervisor_id, string member_number,
                                            string FamilySize, string NameofHousehold, string Age,
                                            string NameofSpouse, string NationalID, string ContactNo,
                                            string Sex, string female_dependants, string male_dependants,
                                            string NoofDependents, string NumberChildrenAgeAbove5years,
                                            string NumberChildrenAgeAbove18years, string NumberAdultsAgeBetween30_45,
                                            string NumberAdultsAgeBetween45_64, string NumberAdultsAgeAbove65,
                                            string SOurceofIncome, string FamilyIncome, string intStateid,
                                            string intCountieid, string intPayamid, string intBomasid,
                                            string latitude, string longitude, string LegalStatus,
                                            string PhotoName, string id_url,
                                            string TransferDate, string TransferUpdateat, string Created_by,
                                            string selectionCriteria, string selectionReason)
    {


        SqlCommand cmd = new SqlCommand();
        cmd.CommandType = CommandType.StoredProcedure;
        cmd.CommandText = "insertbenficiaryDetfromapi";

        cmd.Parameters.AddWithValue("@intIP", intIP);
        cmd.Parameters.AddWithValue("@household_number", household_number);
        cmd.Parameters.AddWithValue("@BeneficiaryType", BeneficiaryType);
        cmd.Parameters.AddWithValue("@GroupId", GroupId);

        cmd.Parameters.AddWithValue("@supervisor_id", supervisor_id);
        cmd.Parameters.AddWithValue("@member_number", member_number);
        cmd.Parameters.AddWithValue("@FamilySize", FamilySize);
        cmd.Parameters.AddWithValue("@NameofHousehold", NameofHousehold);
        cmd.Parameters.AddWithValue("@Age", Age);
        cmd.Parameters.AddWithValue("@NameofSpouse", NameofSpouse);
        cmd.Parameters.AddWithValue("@NationalID", NationalID);
        cmd.Parameters.AddWithValue("@ContactNo", ContactNo);
        cmd.Parameters.AddWithValue("@Sex", Sex);
        cmd.Parameters.AddWithValue("@female_dependants", female_dependants);
        cmd.Parameters.AddWithValue("@male_dependants", male_dependants);
        cmd.Parameters.AddWithValue("@NoofDependents", NoofDependents);
        cmd.Parameters.AddWithValue("@NumberChildrenAgeAbove5years", NumberChildrenAgeAbove5years);
        cmd.Parameters.AddWithValue("@NumberChildrenAgeAbove18years", NumberChildrenAgeAbove18years);
        cmd.Parameters.AddWithValue("@NumberAdultsAgeBetween30_45", NumberAdultsAgeBetween30_45);
        cmd.Parameters.AddWithValue("@NumberAdultsAgeBetween45_64", NumberAdultsAgeBetween45_64);
        cmd.Parameters.AddWithValue("@NumberAdultsAgeAbove65", NumberAdultsAgeAbove65);
        cmd.Parameters.AddWithValue("@SOurceofIncome", SOurceofIncome);
        cmd.Parameters.AddWithValue("@FamilyIncome", FamilyIncome);
        cmd.Parameters.AddWithValue("@intStateid", intStateid);
        cmd.Parameters.AddWithValue("@intCountieid", intCountieid);
        cmd.Parameters.AddWithValue("@intPayamid", intPayamid);
        cmd.Parameters.AddWithValue("@intBomasid", intBomasid);
        cmd.Parameters.AddWithValue("@latitude", latitude);
        cmd.Parameters.AddWithValue("@longitude", longitude);
        cmd.Parameters.AddWithValue("@LegalStatus", LegalStatus);
        cmd.Parameters.AddWithValue("@PhotoName", PhotoName);
        cmd.Parameters.AddWithValue("@id_url", id_url);


        if (TransferDate.Trim() == "" || TransferDate.Trim() == null)
            cmd.Parameters.AddWithValue("@TransferDate", SqlDbType.DateTime).Value = DBNull.Value;
        else
            cmd.Parameters.AddWithValue("@TransferDate", SqlDbType.DateTime).Value = cmf.convertDateIndia(TransferDate);

        if (TransferUpdateat.Trim() == "" || TransferUpdateat.Trim() == null)
            cmd.Parameters.AddWithValue("@TransferUpdateat", SqlDbType.DateTime).Value = DBNull.Value;
        else
            cmd.Parameters.AddWithValue("@TransferUpdateat", SqlDbType.DateTime).Value = cmf.convertDateIndia(TransferUpdateat);
        cmd.Parameters.AddWithValue("@Created_by", Created_by);


        // New Fields
        cmd.Parameters.AddWithValue("@SelectionCriteria", (selectionCriteria != null) ? selectionCriteria : "");
        cmd.Parameters.AddWithValue("@SelectionReason", (selectionReason != null) ? selectionReason : "");

        cmd.Parameters.Add("@ReturnVal", SqlDbType.NVarChar, 100);
        cmd.Parameters["@ReturnVal"].Direction = ParameterDirection.Output;

        con.OpenConnection();
        cmd.CommandType = CommandType.StoredProcedure;
        cmd.Connection = con.GetConnection;
        cmd.ExecuteNonQuery();
        try
        {
            int i = Convert.ToInt32(cmd.Parameters["@ReturnVal"].Value);


            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(cmd, TraceLogOperationType.Insert, i.ToString(), "InsertDataUsingAPI");
                }

            }
            catch (Exception) { }
            #endregion

            return i;
        }
        catch (Exception ex)
        {
            return 0;
        }
        finally
        {
            cmd.Dispose();
            con.CloseConnection();
        }

    }



