    public int UpdBenficiaryDetByAPI(string Id, string Status)
    {
        SqlCommand com = new SqlCommand();
        com.CommandType = CommandType.StoredProcedure;
        com.CommandText = "UpdateBenficiaryDetByAPIID";

        if (Id == "" || Id == null)
            com.Parameters.Add("@intBenid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intBenid", SqlDbType.VarChar).Value = Id.Trim();

        if (Status == "" || Status == null)
            com.Parameters.Add("@statsu", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@statsu", SqlDbType.VarChar).Value = Status.Trim();

        con.OpenConnection();
        com.Connection = con.GetConnection;

        try
        {
            //return com.ExecuteNonQuery();
            int result = Convert.ToInt32(com.ExecuteScalar());

            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(com, TraceLogOperationType.Update, Id.ToString(), "UpdBenficiaryDetByAPI");
                }

            }
            catch (Exception) { }
            #endregion

            return result;
        }
        catch (Exception ex)
        {
            throw ex;
            return 0;
        }
        finally
        {
            com.Dispose();
            con.CloseConnection();
        }
    }

