                cmd.Parameters.Add("@PaidGenerateddate", SqlDbType.DateTime).Value = DBNull.Value;
            else
                cmd.Parameters.Add("@PaidGenerateddate", SqlDbType.DateTime).Value = cmf.convertDateIndia(PaidGenerateddate.Trim());

            if (Paidto.Trim() == "" || Paidto.Trim() == null)
