    public int GetPhotoid(string household_number)
    {

        SqlCommand cmd = new SqlCommand();
        cmd.CommandType = CommandType.StoredProcedure;
        cmd.CommandText = "GetPhotoid";


        cmd.Parameters.AddWithValue("@household_number", household_number);


        cmd.Parameters.Add("@ReturnVal", SqlDbType.NVarChar, 100);
        cmd.Parameters["@ReturnVal"].Direction = ParameterDirection.Output;

        con.OpenConnection();
        cmd.CommandType = CommandType.StoredProcedure;
        cmd.Connection = con.GetConnection;
        cmd.ExecuteNonQuery();
        try
        {
            int i = Convert.ToInt32(cmd.Parameters["@ReturnVal"].Value);
            return i;
        }
        catch (Exception ex)
        {
            return 0;
        }
        finally
        {
            cmd.Dispose();
            con.CloseConnection();
        }

    }

