    public int InsertAlternate(string household_number,
                              string Secondalternate_number, string Name2ndAlternatePayee,
                              string SecondAlternatePayeeAge, string SecondAlternateNationalID,
                              string SecondAlternatePayeeGender, string SecondAlternatePayeeMobile,
                              string SecondAlternatepayeePhotoName, string id, string created_dt, string supervisor_id)
    {

        SqlCommand cmd = new SqlCommand();
        cmd.CommandType = CommandType.StoredProcedure;
        cmd.CommandText = "InsertAlternate";

        cmd.Parameters.AddWithValue("@household_number", household_number);
        cmd.Parameters.AddWithValue("@Secondalternate_number", Secondalternate_number);
        cmd.Parameters.AddWithValue("@Name2ndAlternatePayee", Name2ndAlternatePayee);
        cmd.Parameters.AddWithValue("@SecondAlternatePayeeAge", SecondAlternatePayeeAge);
        cmd.Parameters.AddWithValue("@SecondAlternateNationalID", SecondAlternateNationalID);
        cmd.Parameters.AddWithValue("@SecondAlternatePayeeGender", SecondAlternatePayeeGender);
        cmd.Parameters.AddWithValue("@SecondAlternatePayeeMobile", SecondAlternatePayeeMobile);
        cmd.Parameters.AddWithValue("@SecondAlternatepayeePhotoName", SecondAlternatepayeePhotoName);
        cmd.Parameters.AddWithValue("@id", id);
        cmd.Parameters.AddWithValue("@created_dt", Convert.ToDateTime(created_dt));
        cmd.Parameters.AddWithValue("@supervisor_id", supervisor_id);

        con.OpenConnection();
        cmd.Connection = con.GetConnection;

        try
        {
            cmd.ExecuteNonQuery();


            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(cmd, TraceLogOperationType.Insert, household_number.ToString(), "InsertAlternate");
                }

            }
            catch (Exception) { }
            #endregion

            return 1;
        }
        catch (Exception ex)
        {
            return 0;
        }
        finally
        {
            cmd.Dispose();
            con.CloseConnection();
