    public int TransferAPIDashAfterConfirmation(string Id, string intStateid, string intCountyid, string intPayamid, string intBomaid, string Modified_by)
    {
        SqlCommand com = new SqlCommand();
        com.CommandType = CommandType.StoredProcedure;
        com.CommandText = "sp_TransferbenfdetBulkAfterConfirmation";



        if (Id == "" || Id == null)
            com.Parameters.Add("@Benid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Benid", SqlDbType.VarChar).Value = Id.Trim();
        if (intStateid == "" || intStateid == null || intStateid == "--Select--")
            com.Parameters.Add("@intStateid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intStateid", SqlDbType.VarChar).Value = intStateid.Trim();

        if (intCountyid == "" || intCountyid == null || intCountyid == "--Select--")
            com.Parameters.Add("@intCountyid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intCountyid", SqlDbType.VarChar).Value = intCountyid.Trim();

        if (intPayamid == "" || intPayamid == null || intPayamid == "--Select--")
            com.Parameters.Add("@intPayamid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intPayamid", SqlDbType.VarChar).Value = intPayamid.Trim();

        if (intBomaid == "" || intBomaid == null || intBomaid == "--Select--")
            com.Parameters.Add("@intBomaUid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@intBomaUid", SqlDbType.VarChar).Value = intBomaid.Trim();

        if (Modified_by == "" || Modified_by == null || Modified_by == "--Select--")
            com.Parameters.Add("@Modified_by", SqlDbType.VarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@Modified_by", SqlDbType.VarChar).Value = Modified_by.Trim();


        //string intStateid, string intCountyid,string intPayamid,string intBomaid

        con.OpenConnection();
        com.Connection = con.GetConnection;

        try
        {
            //return com.ExecuteNonQuery();
            return Convert.ToInt32(com.ExecuteScalar());
        }
        catch (Exception ex)
        {

            throw ex;
            return 0;
        }
        finally
        {
            com.Dispose();
            con.CloseConnection();
        }
    }


