    public int InsertAPIFailure_StatusIPidNew(string Household_Number, string Failure_Message, string TransferDate, string IPid, string Bomaid, string NameofHousehold)
    {

        SqlCommand cmd = new SqlCommand();
        cmd.CommandType = CommandType.StoredProcedure;
        cmd.CommandText = "InsertAPIFailure_StatusIPidNew";


        cmd.Parameters.AddWithValue("@Household_Number", Household_Number);
        cmd.Parameters.AddWithValue("@Failure_Message", Failure_Message);
        if (TransferDate.Trim() == "" || TransferDate.Trim() == null)
            cmd.Parameters.AddWithValue("@TransferDate", SqlDbType.DateTime).Value = DBNull.Value;
        else
            cmd.Parameters.AddWithValue("@TransferDate", SqlDbType.DateTime).Value = cmf.convertDateIndia(TransferDate);


        cmd.Parameters.AddWithValue("@IPid", IPid);

        if (Bomaid.Trim() == "" || Bomaid.Trim() == null)
            cmd.Parameters.AddWithValue("@Bomaid", SqlDbType.VarChar).Value = DBNull.Value;
        else
            cmd.Parameters.AddWithValue("@Bomaid", SqlDbType.VarChar).Value = Bomaid;

        if (NameofHousehold.Trim() == "" || NameofHousehold.Trim() == null)
            cmd.Parameters.AddWithValue("@NameofHousehold", SqlDbType.VarChar).Value = DBNull.Value;
        else
            cmd.Parameters.AddWithValue("@NameofHousehold", SqlDbType.VarChar).Value = NameofHousehold;



        con.OpenConnection();
        cmd.Connection = con.GetConnection;

        try
        {
            cmd.ExecuteNonQuery();


            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(cmd, TraceLogOperationType.Insert, Household_Number.ToString(), "InsertAPIFailure_StatusIPidNew");
                }

            }
            catch (Exception) { }
            #endregion
            return 1;
        }
        catch (Exception ex)
        {
            return 0;
        }
        finally
        {
            cmd.Dispose();
            con.CloseConnection();
        }

    }
