    public int InsertTotalBenDatathroughAPI(string id, string supervisor_id, string partner_code, string household_number,
   string beneficiary_type, string group_number, string member_number,
   string household_size, string household_name, string age, string marital_status,
   string spouse_name, string id_number, string phone_number, string gender, string
                     female_dependants, string male_dependants, string zero_five, string six_eighteen,
   string nineteen_forty_five, string forty_six_sixty_five, string sixty_six, string income_household,
   string average_household, string state, string county, string payam, string boma, string latitude,
   string longitude, string legal_status, string status, string
                     created_at, string updated_at, string stored_at, string photo_url)
    {

        SqlCommand cmd = new SqlCommand();
        cmd.CommandType = CommandType.StoredProcedure;
        cmd.CommandText = "insertbenficiaryDetfromapialldata";

        cmd.Parameters.AddWithValue("@id", id);
        cmd.Parameters.AddWithValue("@supervisor_id", supervisor_id);
        cmd.Parameters.AddWithValue("@partner_code", partner_code);
        cmd.Parameters.AddWithValue("@household_number", household_number);
        cmd.Parameters.AddWithValue("@beneficiary_type", beneficiary_type);
        cmd.Parameters.AddWithValue("@group_number", group_number);
        cmd.Parameters.AddWithValue("@member_number", member_number);
        cmd.Parameters.AddWithValue("@household_size", household_size);
        cmd.Parameters.AddWithValue("@household_name", household_name);
        cmd.Parameters.AddWithValue("@age", age);
        cmd.Parameters.AddWithValue("@marital_status", marital_status);
        cmd.Parameters.AddWithValue("@spouse_name", spouse_name);
        cmd.Parameters.AddWithValue("@id_number", id_number);
        cmd.Parameters.AddWithValue("@phone_number", phone_number);
        cmd.Parameters.AddWithValue("@gender", gender);
        cmd.Parameters.AddWithValue("@female_dependants", female_dependants);
        cmd.Parameters.AddWithValue("@male_dependants", male_dependants);
        cmd.Parameters.AddWithValue("@zero_five", zero_five);
        cmd.Parameters.AddWithValue("@six_eighteen", six_eighteen);
        cmd.Parameters.AddWithValue("@nineteen_forty_five", nineteen_forty_five);
        cmd.Parameters.AddWithValue("@forty_six_sixty_five", forty_six_sixty_five);
        cmd.Parameters.AddWithValue("@sixty_six", sixty_six);
        cmd.Parameters.AddWithValue("@income_household", income_household);
        cmd.Parameters.AddWithValue("@average_household", average_household);
        cmd.Parameters.AddWithValue("@state", state);
        cmd.Parameters.AddWithValue("@county", county);
        cmd.Parameters.AddWithValue("@payam", payam);
        cmd.Parameters.AddWithValue("@boma", boma);
        cmd.Parameters.AddWithValue("@latitude", latitude);
        cmd.Parameters.AddWithValue("@longitude", longitude);
        cmd.Parameters.AddWithValue("@legal_status", legal_status);
        cmd.Parameters.AddWithValue("@status", status);
        cmd.Parameters.AddWithValue("@created_at", Convert.ToDateTime(created_at));
        if (updated_at == "" || updated_at == null || updated_at == "--Select--")
            cmd.Parameters.AddWithValue("@updated_at", SqlDbType.VarChar).Value = DBNull.Value;
        else
            cmd.Parameters.AddWithValue("@updated_at", SqlDbType.DateTime).Value = Convert.ToDateTime(updated_at);

        if (stored_at == "" || stored_at == null || stored_at == "--Select--")
            cmd.Parameters.AddWithValue("@stored_at", SqlDbType.VarChar).Value = DBNull.Value;
        else
            cmd.Parameters.AddWithValue("@stored_at", SqlDbType.DateTime).Value = Convert.ToDateTime(stored_at);



        cmd.Parameters.AddWithValue("@photo_url", photo_url);





        cmd.Parameters.Add("@ReturnVal", SqlDbType.NVarChar, 100);
        cmd.Parameters["@ReturnVal"].Direction = ParameterDirection.Output;

        con.OpenConnection();
        cmd.CommandType = CommandType.StoredProcedure;
        cmd.Connection = con.GetConnection;
        cmd.ExecuteNonQuery();
        try
        {
            int i = Convert.ToInt32(cmd.Parameters["@ReturnVal"].Value);


            #region TraceLog Implementation
            try
            {
                string appSettingValue = System.Configuration.ConfigurationManager.AppSettings["TraceLogs"];

                if (appSettingValue != null && appSettingValue.ToLower() == "true")
                {
                    CreateAudit(cmd, TraceLogOperationType.Insert, i.ToString(), "InsertTotalBenDatathroughAPI");
                }

            }
            catch (Exception) { }
            #endregion

            return i;
        }
        catch (Exception ex)
        {
            return 0;
        }
        finally
        {
            cmd.Dispose();
            con.CloseConnection();
        }

    }
