        com.CommandType = CommandType.StoredProcedure;
        com.CommandText = "InsertAuditLog";

        if (userId == "" || userId == null)
            com.Parameters.Add("@userId", SqlDbType.NVarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@userId", SqlDbType.NVarChar).Value = userId.Trim();

        if (pKey == "" || pKey == null)
            com.Parameters.Add("@pKey", SqlDbType.NVarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@pKey", SqlDbType.NVarChar).Value = pKey.Trim();

        if (xmlObjectLog == "" || xmlObjectLog == null)
            com.Parameters.Add("@xmlObjectLog", SqlDbType.Xml).Value = DBNull.Value;
        else
            com.Parameters.Add("@xmlObjectLog", SqlDbType.Xml).Value = xmlObjectLog;


        if (commandMethod == "" || commandMethod == null)
            com.Parameters.Add("@commandMethod", SqlDbType.NVarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@commandMethod", SqlDbType.NVarChar).Value = commandMethod.Trim();

        if (commandText == "" || commandText == null)
            com.Parameters.Add("@commandText", SqlDbType.NVarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@commandText", SqlDbType.NVarChar).Value = commandText.Trim();

        if (operationType == "" || operationType == null)
            com.Parameters.Add("OperationType", SqlDbType.NVarChar).Value = DBNull.Value;
        else
            com.Parameters.Add("@OperationType", SqlDbType.NVarChar).Value = operationType.Trim();

        con.OpenConnection();
        com.Connection = con.GetConnection;

        try
        {
            //return com.ExecuteNonQuery();
            return Convert.ToInt32(com.ExecuteScalar());
        }
        catch (Exception ex)
        {

            throw ex;
            return -1;
        }
        finally
        {
            com.Dispose();
            con.CloseConnection();
        }
    }

