    public string GenerateGRNewSerialNumber(string prefix)
    {
        // Format must be 
        // NGBV000001 for NGBV
        // GBV000001 for GBV

        string strNewGRSerialNumber = "";
        string strLastSN = "";

        //Retrieve latest Serial number
        con.OpenConnection();
        SqlDataAdapter da;
        DataSet ds = new DataSet();
        try
        {
            //NGBV 
            if (prefix == "NGBV")
            {
                da = new SqlDataAdapter("getLastNGBVSerialNumber", con.GetConnection);
            }
            else //GBV
            {
                //StoredProcedure to be implemented with GBV module (remove "da=null;" when ready)
                //da = new SqlDataAdapter("getLastGBVSerialNumber", con.GetConnection);
                da = null; //
            }
            da.SelectCommand.CommandType = CommandType.StoredProcedure;
            da.Fill(ds);
            con.CloseConnection();
            strLastSN = ds.Tables[0].Rows[0]["SerialNumber"].ToString();
        }
        catch (Exception ex)
        {
            throw ex;
        }
        finally
        {
            con.CloseConnection();
        }

        //Split into string and number
        string strSNNumber = strLastSN.Replace(prefix, "");
        int iSNumber = Convert.ToInt32(strSNNumber);
        iSNumber = iSNumber + 1;
        strSNNumber = iSNumber.ToString();
        //Padding to 6 lenght string
        strSNNumber = strSNNumber.PadLeft(6, '0');
        strNewGRSerialNumber = prefix + strSNNumber;
        //Number increment
        //join string anad number
        return strNewGRSerialNumber;
    }

    public byte[] zipString(string FileContent, string FileName)
    {
        using (Stream memOutput = new MemoryStream())
        {
            using (ZipOutputStream zipOut = new ZipOutputStream(memOutput))
            {
                using (StreamWriter writer = new StreamWriter(zipOut))
                {
                    ZipEntry newEntry = new ZipEntry(FileName);
                    newEntry.DateTime = DateTime.Now;

                    zipOut.PutNextEntry(newEntry);

                    writer.Write(FileContent);

                    writer.Flush();
                    zipOut.Finish();

                    byte[] bytes = new byte[memOutput.Length];
                    memOutput.Seek(0, SeekOrigin.Begin);
                    memOutput.Read(bytes, 0, bytes.Length);

                    return bytes;
                }
            }
        }
    }

    //Creation of a String with full content of CSV export from a DataTable
    public StringBuilder CreateCSVString(DataTable ContentTable)
    {
        StringBuilder columnbind = new StringBuilder();

        int iColumnCount = ContentTable.Columns.Count;
        int iRowCount = ContentTable.Rows.Count;


        for (int iCounter = 0; iCounter < iColumnCount; iCounter++)
        {
            columnbind.Append(ContentTable.Columns[iCounter].ColumnName + ',');
        }

        columnbind.Append("\r\n");

        for (int i = 0; i < iRowCount; i++)
        {
            for (int k = 0; k < iColumnCount; k++)
            {
                if (ContentTable.Rows[i][k].ToString() != "&nbsp;" && ContentTable.Rows[i][k] != null && ContentTable.Rows[i][k].ToString() != string.Empty)
                    columnbind.Append(ContentTable.Rows[i][k].ToString().Replace(',', '-') + ',');
                else
                    columnbind.Append("N/A" + ',');
            }

            columnbind.Append("\r\n");
        }

        return columnbind;
    }

